// ---------------------------------------------------------------------------
// uiVM: a separate realm with no access to loader-scope variables
// ---------------------------------------------------------------------------

let paletteReads = 0
let styleId = 0
const styles: any[] = []
const storage = new Map<string, unknown>()
const timers: Array<{ fn: () => void; delay: number }> = []

const palette = `:root {
  --nt-primary: #4f8cff;
  --nt-primary-container: #244a80;
  --nt-surface: #101014;
  --nt-surface-container: #17171c;
  --nt-surface-container-high: #1d1d24;
  --nt-surface-container-low: #141419;
  --nt-on-surface: #e6e6ea;
  --nt-on-surface-variant: #b4b4c0;
  --nt-mode: dark;
}
`

const html = {
    attributes: {} as Record<string, string>,
    getAttribute(name: string) {
        return this.attributes[name] ?? null
    },
    setAttribute(name: string, value: string) {
        this.attributes[name] = value
    },
}

const head = {
    children: [] as any[],
    append(child: any) {
        this.children.push(child)
    },
}

function makeElement(tag: string) {
    const element = {
        id: `sim-${++styleId}`,
        tag,
        text: "",
        attributes: {} as Record<string, string>,
        setAttribute(name: string, value: string) {
            this.attributes[name] = value
        },
        getAttribute(name: string) {
            return this.attributes[name] ?? null
        },
        setText(value: string) {
            this.text = value
        },
        async getText() {
            return this.text
        },
        setDataAttribute(name: string, value: string) {
            this.attributes[`data-${name}`] = value
        },
        remove() {
            this.text = ""
            const index = styles.indexOf(this)
            if (index >= 0) styles.splice(index, 1)
        },
        async append(child: any) {
            this.children = this.children || []
            this.children.push(child)
        },
    }
    styles.push(element)
    return element
}

const readyCallbacks: Array<() => void> = []
const mainTabCallbacks: Array<() => void> = []

const uiVM = vm.createContext({
    $storage: {
        get: (key: string) => storage.get(key),
        set: (key: string, value: unknown) => {
            storage.set(key, value)
        },
    },
    $os: {
        homeDir: () => "/home/seanime",
        readFile: (_path: string) => {
            paletteReads++
            return new TextEncoder().encode(palette)
        },
    },
    DOMElement: function () {},
})

let uiCallback: any
try {
    // Goja evaluates the callback in the uiVM. Re-evaluating its source here
    // reproduces that: a callback that closes over loader-scope names fails
    // now, instead of only in the real app.
    uiCallback = vm.runInContext(`(${registered.toString()})`, uiVM)
    check("callback is self-contained in the uiVM", typeof uiCallback === "function")
} catch (error) {
    check("callback is self-contained in the uiVM", false, (error as Error).message)
    process.exit(1)
}

const ctx = {
    state: (initial: unknown) => {
        let value = initial
        return {
            get: () => value,
            set: (next: unknown) => {
                value = next
            },
        }
    },
    fieldRef: (initial: string) => {
        const ref: any = {
            current: initial,
            setValue: (next: string) => {
                ref.current = next
            },
            onValueChange: () => {},
        }
        return ref
    },
    newTray: () => {
        throw new Error("tray unavailable in this runtime")
    },
    dom: {
        onReady: (callback: () => void) => {
            readyCallbacks.push(callback)
        },
        onMainTabReady: (callback: () => void) => {
            mainTabCallbacks.push(callback)
        },
        queryOne: async (selector: string) => {
            if (selector === "head") return head
            if (selector === "html") return html
            if (selector === '[data-noctalia="1"]') {
                return styles.find((element) => element.attributes["data-noctalia"] === "1") ?? null
            }
            return null
        },
        createElement: async (tag: string) => makeElement(tag),
        asElement: (id: string) => styles.find((element) => element.id === id) ?? null,
    },
    setTimeout: (fn: () => void) => {
        return fn
    },
    setInterval: (fn: () => void, delay: number) => {
        timers.push({ fn, delay })
        return () => {}
    },
    fetch: async () => ({ ok: false, status: 404, text: () => "" }),
}

try {
    uiCallback.call(uiVM, ctx)
    check("callback runs against the uiVM context", true)
} catch (error) {
    check("callback runs against the uiVM context", false, (error as Error).message)
    process.exit(1)
}

check("ctx.dom.onReady registered a callback", readyCallbacks.length === 1)
check("ctx.dom.onMainTabReady registered a callback", mainTabCallbacks.length === 1)
check(
    "polling interval is scheduled",
    timers.length === 1 && timers[0].delay === 2000,
    timers.length ? `delay=${timers[0].delay}` : "no interval",
)

// onReady fires once when the client is ready.
try {
    readyCallbacks[0]?.()
    await flush()
} catch (error) {
    check("onReady callback runs", false, (error as Error).message)
}

check("onReady reads the palette once", paletteReads === 1, `reads=${paletteReads}`)
